contract InvMutTest
{
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function test(uint _val) public
    {
        // Before initialization: SetMinSum must succeed (P) / revert (M)
        bool okBefore; c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { okBefore = false; } else { okBefore = true; }

        // Initialize
        c.Initialized(); if (__ESBMC_reverted()) return;

        // After initialization: SetMinSum must revert (P) / succeed (M)
        bool okAfter; c.SetMinSum(_val); bool __rev1 = __ESBMC_reverted(); if (__rev1) { okAfter = false; } else { okAfter = true; }

        assert(okBefore && !okAfter);
    }
}

