// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _test(uint256 _val) internal {
        bool okBefore;
        try c.SetMinSum(_val) { okBefore = true; } catch { okBefore = false; }
        try c.Initialized() {} catch { return; }
        bool okAfter;
        try c.SetMinSum(_val) { okAfter = true; } catch { okAfter = false; }
        assertTrue(okBefore && !okAfter);
    }

    function testFuzz_test(uint256 _val) public {
        _test(_val);
    }

    receive() external payable {}
}
